private inline fun sfDetailIcon(
    name: String,
    viewportWidth: Float,
    viewportHeight: Float,
    block: ImageVector.Builder.() -> Unit,
): ImageVector {
    val scale = 24f / maxOf(viewportWidth, viewportHeight)
    return ImageVector.Builder(
        name = name,
        defaultWidth = (viewportWidth * scale).dp,
        defaultHeight = (viewportHeight * scale).dp,
        viewportWidth = viewportWidth,
        viewportHeight = viewportHeight,
    ).apply(block).build()
}

private fun ImageVector.Builder.addSfDetailPath(pathData: String) {
    addPath(
        pathData = PathParser().parsePathString(pathData).toNodes(),
        fill = SolidColor(Color.Black),
        fillAlpha = 0.85f,
    )
}
